-- DB08 F2 current-actor commands and immutable effects.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(40);
SELECT ok(NOT has_table_privilege('authenticated','app_private.finance_fee_rules','SELECT,INSERT,UPDATE,DELETE'),'clients have no fee-table DML');
SELECT ok(NOT has_table_privilege('service_role','app_private.finance_fee_obligations','SELECT,INSERT,UPDATE,DELETE'),'service role has no charge shortcut');
SELECT ok(has_function_privilege('authenticated','app.configure_finance_fee(uuid,uuid,text,text,text,text,integer,numeric,date,date,text,text)','EXECUTE'),'authenticated may attempt checked fee configuration');
SELECT ok(has_function_privilege('authenticated','app.assess_finance_fee(uuid,uuid,uuid,date,date,date,uuid)','EXECUTE'),'authenticated may attempt checked fee assessment');
SELECT ok(NOT has_function_privilege('authenticated','app_private.db08_fee_receipt(text,uuid,text,bytea,uuid,uuid)','EXECUTE'),'receipt internals not client callable');
SELECT is((SELECT count(*) FROM pg_class WHERE relname='finance_fee_publications' AND relrowsecurity AND relforcerowsecurity),1::bigint,'publication history forced RLS');
\ir fixture_commands.sql
SET ROLE authenticated;
SELECT * FROM jsonb_to_record(app.configure_finance_fee('08000000-0000-4000-8000-000000000003','08000000-0000-4000-8000-000000000004','TUITION','Tuition','TUITION_2026','MONTHLY',2,10000,'2026-01-01','2026-12-31','Initial school fee','initial-fee')) AS x(source_id uuid,resource_id uuid,campus_id uuid) \gset f_
RESET ROLE;
SELECT is((SELECT count(*) FROM app_private.finance_fee_rules),1::bigint,'live staff creates one scoped fee rule');
SELECT is((SELECT count(*) FROM app_private.finance_fee_rule_revisions WHERE revision=1),1::bigint,'first configured price is retained');
SELECT is((SELECT count(*) FROM app_private.finance_fee_publications WHERE rule_id=:'f_resource_id'::uuid AND state='PUBLISHED'),1::bigint,'initial fee published atomically');
SELECT lives_ok($test$SET CONSTRAINTS ALL IMMEDIATE$test$,'published fee has an actual matching completed receipt FK');
SELECT is((SELECT count(*) FROM app_private.command_receipts WHERE command_kind='finance.fee.configure'),1::bigint,'one configuration receipt');
SELECT is((SELECT count(*) FROM app_private.audit_events WHERE event_type='finance.fee.configure'),1::bigint,'one configuration audit');
SELECT is((SELECT count(*) FROM app_private.outbox_events WHERE event_type='finance.fee.configure'),1::bigint,'one configuration outbox event');
SELECT is((app.configure_finance_fee('08000000-0000-4000-8000-000000000003','08000000-0000-4000-8000-000000000004','TUITION','Tuition','TUITION_2026','MONTHLY',2,10000,'2026-01-01','2026-12-31','Initial school fee','initial-fee')->>'source_id')::uuid,:'f_source_id'::uuid,'authorized exact-key retry returns same publication');
SELECT is((SELECT count(*) FROM app_private.finance_fee_rules),1::bigint,'configuration replay adds no rule');
SELECT throws_ok($test$SELECT app.configure_finance_fee('08000000-0000-4000-8000-000000000003','08000000-0000-4000-8000-000000000004','TUITION','Tuition','TUITION_2026','MONTHLY',2,12000,'2026-01-01','2026-12-31','Initial school fee','initial-fee')$test$,'P0001'::char(5),NULL::text,'same command key different price rejected');
SELECT throws_ok($test$SELECT app.configure_finance_fee('08000000-0000-4000-8000-000000000003','08000000-0000-4000-8000-000000000004','TUITION','Tuition','TUITION_2026','MONTHLY',2,10000,'2026-01-01','2026-12-31','Initial school fee','other')$test$,'23505'::char(5),NULL::text,'new command key cannot create duplicate rule');
SELECT throws_ok($test$SELECT app.configure_finance_fee('08000000-0000-4000-8000-000000000003','08000000-0000-4000-8000-000000000004','TUITION','Tuition','OTHER','MONTHLY',3,10000,'2026-01-01','2026-12-31','Initial school fee','other')$test$,'P0001'::char(5),NULL::text,'school currency precision cannot change silently');
SELECT throws_ok($test$SELECT app.configure_finance_fee('08000000-0000-4000-8000-000000000003','08000000-0000-4000-8000-000000000004','TUITION','Renamed','OTHER','MONTHLY',2,10000,'2026-01-01','2026-12-31','Initial school fee','other')$test$,'P0001'::char(5),NULL::text,'category cannot be relabelled through initial fee API');
SELECT throws_ok($test$SELECT app.configure_finance_fee('08000000-0000-4000-8000-000000000003','08000000-0000-4000-8000-000000000004','TUITION','Tuition','OTHER','MONTHLY',2,100.1,'2026-01-01','2026-12-31','Initial school fee','invalid')$test$,'P0001'::char(5),NULL::text,'fractional minor unit rejected before any record');
SELECT throws_ok($test$SELECT app.configure_finance_fee('08000000-0000-4000-8000-000000000003','08000000-0000-4000-8000-000000000004','TUITION','Tuition','OTHER','MONTHLY',2,-1,'2026-01-01','2026-12-31','Initial school fee','invalid')$test$,'P0001'::char(5),NULL::text,'negative gross fee rejected');
SELECT throws_ok($test$SELECT app.configure_finance_fee('08000000-0000-4000-8000-000000000099','08000000-0000-4000-8000-000000000004','TUITION','Tuition','OTHER','MONTHLY',2,10000,'2026-01-01','2026-12-31','Initial school fee','invalid')$test$,'P0001'::char(5),NULL::text,'unknown campus denied');
SELECT is((SELECT count(*) FROM app_private.command_receipts),1::bigint,'failed fee attempts emit no receipts');
SELECT id AS rev_id FROM app_private.finance_fee_rule_revisions WHERE rule_id=:'f_resource_id'::uuid AND revision=1 \gset
SET ROLE authenticated;
SELECT * FROM jsonb_to_record(app.assess_finance_fee((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026')::uuid,'08000000-0000-4000-8000-000000000006'::uuid,(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026') AND revision=1)::uuid,'2026-02-01'::date,'2026-02-28'::date,'2026-03-05'::date,'08000000-0000-4000-8000-000000000101'::uuid)) AS x(source_id uuid,resource_id uuid,campus_id uuid) \gset charge_
RESET ROLE;
SELECT is((SELECT count(*) FROM app_private.finance_fee_obligations WHERE id=:'charge_resource_id'::uuid AND person_id='08000000-0000-4000-8000-000000000006' AND gross_amount_minor=10000),1::bigint,'full-price charge bound to canonical Person and configured amount');
SELECT is((app.assess_finance_fee((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026')::uuid,'08000000-0000-4000-8000-000000000006'::uuid,(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026') AND revision=1)::uuid,'2026-02-01'::date,'2026-02-28'::date,'2026-03-05'::date,'08000000-0000-4000-8000-000000000101'::uuid)->>'source_id')::uuid,:'charge_source_id'::uuid,'authorized same-key assessment retry returns same charge');
SELECT is((SELECT count(*) FROM app_private.command_receipts WHERE command_kind='finance.charge.assess'),1::bigint,'charge replay does not double receipt');
SELECT is((SELECT count(*) FROM app_private.audit_events WHERE event_type='finance.charge.assess'),1::bigint,'one assessment audit');
SELECT is((SELECT count(*) FROM app_private.outbox_events WHERE event_type='finance.charge.assess'),1::bigint,'one assessment outbox');
SELECT throws_ok($test$SELECT app.assess_finance_fee((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026')::uuid,'08000000-0000-4000-8000-000000000006'::uuid,(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026') AND revision=1)::uuid,'2026-02-01'::date,'2026-02-28'::date,'2026-03-06'::date,'08000000-0000-4000-8000-000000000101'::uuid)$test$,'P0001'::char(5),NULL::text,'same charge command key with changed due date conflicts');
SELECT throws_ok($test$SELECT app.assess_finance_fee((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026')::uuid,'08000000-0000-4000-8000-000000000006'::uuid,(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026') AND revision=1)::uuid,'2026-02-01'::date,'2026-02-28'::date,'2026-03-05'::date,'08000000-0000-4000-8000-000000000102'::uuid)$test$,'P0001'::char(5),NULL::text,'second key cannot reassess same fee period');
SELECT throws_ok($test$SELECT app.assess_finance_fee((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026')::uuid,'08000000-0000-4000-8000-000000000006'::uuid,(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026') AND revision=1)::uuid,'2026-02-15'::date,'2026-03-14'::date,'2026-03-05'::date,'08000000-0000-4000-8000-000000000102'::uuid)$test$,'P0001'::char(5),NULL::text,'overlapping fee period denied');
SELECT throws_ok($test$SELECT app.assess_finance_fee((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026')::uuid,'08000000-0000-4000-8000-000000000099'::uuid,(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026') AND revision=1)::uuid,'2026-02-01'::date,'2026-02-28'::date,'2026-03-05'::date,'08000000-0000-4000-8000-000000000102'::uuid)$test$,'P0001'::char(5),NULL::text,'unknown Person denied');
SELECT * FROM jsonb_to_record(app.assess_finance_fee((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026')::uuid,'08000000-0000-4000-8000-000000000006'::uuid,(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026') AND revision=1)::uuid,'2026-03-01'::date,'2026-03-31'::date,'2026-03-05'::date,'08000000-0000-4000-8000-000000000102'::uuid)) AS x(source_id uuid,resource_id uuid,campus_id uuid) \gset march_
SELECT is((SELECT count(*) FROM app_private.finance_fee_obligations),2::bigint,'disjoint March period produces distinct retained charge');
SELECT throws_ok($test$SELECT app.assess_finance_fee((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026')::uuid,'08000000-0000-4000-8000-000000000006'::uuid,'08000000-0000-4000-8000-000000000099'::uuid,'2026-04-01'::date,'2026-04-30'::date,'2026-03-05'::date,'08000000-0000-4000-8000-000000000103'::uuid)$test$,'P0001'::char(5),NULL::text,'unpublished revision cannot assess');
SELECT throws_ok($test$SELECT app.assess_finance_fee((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026')::uuid,'08000000-0000-4000-8000-000000000006'::uuid,(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026') AND revision=1)::uuid,'2027-01-01'::date,'2027-01-31'::date,'2026-03-05'::date,'08000000-0000-4000-8000-000000000103'::uuid)$test$,'P0001'::char(5),NULL::text,'year mismatch cannot assess');
SET ROLE schoolos_schema_owner; UPDATE app_private.operation_contracts SET enabled=false WHERE code='finance.charge.assess'; RESET ROLE;
SELECT throws_ok($test$SELECT app.assess_finance_fee((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026')::uuid,'08000000-0000-4000-8000-000000000006'::uuid,(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026') AND revision=1)::uuid,'2026-04-01'::date,'2026-04-30'::date,'2026-03-05'::date,'08000000-0000-4000-8000-000000000104'::uuid)$test$,'P0001'::char(5),NULL::text,'disabled assessment operation denied');
SET ROLE schoolos_schema_owner; UPDATE app_private.operation_contracts SET enabled=true WHERE code='finance.charge.assess'; RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_set(current_setting('request.jwt.claims')::jsonb,'{exp}','1'::jsonb)::text,true);
SELECT throws_ok($test$SELECT app.assess_finance_fee((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026')::uuid,'08000000-0000-4000-8000-000000000006'::uuid,(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026') AND revision=1)::uuid,'2026-04-01'::date,'2026-04-30'::date,'2026-03-05'::date,'08000000-0000-4000-8000-000000000104'::uuid)$test$,'P0001'::char(5),NULL::text,'expired JWT denied');
SELECT set_config('request.jwt.claims',jsonb_set(current_setting('request.jwt.claims')::jsonb,'{exp}',to_jsonb(floor(extract(epoch FROM clock_timestamp()+interval '1 hour'))::bigint))::text,true);
SET ROLE schoolos_schema_owner; UPDATE app_private.assignment_permission_scopes SET revoked_at=clock_timestamp() WHERE id='08000000-0000-4000-8000-000000000018'; RESET ROLE;
SELECT throws_ok($test$SELECT app.assess_finance_fee((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026')::uuid,'08000000-0000-4000-8000-000000000006'::uuid,(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='TUITION_2026') AND revision=1)::uuid,'2026-04-01'::date,'2026-04-30'::date,'2026-03-05'::date,'08000000-0000-4000-8000-000000000104'::uuid)$test$,'P0001'::char(5),NULL::text,'permission scope revocation denies current assessment');
SELECT is((SELECT count(*) FROM app_private.finance_fee_obligations),2::bigint,'rejected operations leave charge history intact');
SELECT is((SELECT count(*) FROM app_private.command_receipts),3::bigint,'failed operations produce no extra receipts');
SELECT * FROM finish();
ROLLBACK;
